mapper.select:
SELECT * FROM (SELECT T.* FROM( SELECT distinct ETR_ENTRUST_ADD.TARGET_TYPE, #{effectFlag} effectFlag, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, case when FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN FIN_PRODUCT_ISSUE.ISSUE_DATE else FIN_PRODUCT_ISSUE.TENDER_SDATE end as issueDate, CASE WHEN FIN_PRODUCT_ISSUE.ISSUE_CLASS IN ('02', '03') THEN '01' ELSE NULL END AS firstBidStatus, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, CASE WHEN det.PORTFOLIO_ID IS NULL THEN ETR_ENTRUST.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, CASE WHEN det.PORTFOLIO_NAME IS NULL THEN PTL_PORTFOLIO.portfolio_name ELSE det.portfolio_name END portfolioName, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND fpt.TYPE_9 = '01' THEN 'F21' ELSE ETR_ENTRUST_ADD.ASSET_TYPE END AS finprodType2, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F07', 'F08') AND ETR_ENTRUST.PS IN ('03', '04', 'T56', 'T93', 'T94', 'T95', 'T96', 'T01') THEN NVL(ETR_ENTRUST_ADD.TERM_TYPE,ETR_ENTRUST.STOCK_ID) else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') THEN ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') AND ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST.PS IN ('T56', 'T92', 'T93','T94','T95','T96') THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, /*decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',decode(ETR_ENTRUST.PS,'T03',ETR_ENTRUST.ENTRUST_AMT, NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0)),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F17',NVL(ETR_ENTRUST.ENTRUST_NUM *100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt,*/ decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',nvl(ETR_ENTRUST.ENTRUST_AMT,nvl(ETR_ENTRUST.ENTRUST_NUM * 100,0)),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F17',NVL(ETR_ENTRUST.ENTRUST_NUM *100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F17',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, B.realName realName, ETR_ENTRUST.REMARK remark, /*nvl(btm1.OUTPUT_VALUE_1,btm.busi_type) busiTypePosition,*/ CASE WHEN ETR_ENTRUST.TRADE_MARKET in ('03','04') then ETR_ENTRUST_ADD.BUSI_TYPE_POSITION else nvl(btm1.OUTPUT_VALUE_1,btm.busi_type) end busiTypePosition, nvl(SECT.sec_acct_name, ssai.sec_acct_name) secAcctId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F08' THEN DECODE( ETR_ENTRUST_ADD.SETTLE_SPREED, 1, '01', 2, '02', 3, '03') ELSE DECODE( ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02', 2, '03') END AS settleSpeed, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F01', 'F02', 'F03', 'F04', 'F05', 'F06', 'F09') THEN '' ELSE TO_CHAR(ETR_ENTRUST_ADD.TERM_DAYS) END AS termDays, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F17' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN case when FIN_PRODUCT.COUPON_SPECIES = '01' AND FIN_PRODUCT_ISSUE.INT_TYPE = '02' THEN SDLDATA.ITEM_VALUE || '+' || to_char(FIN_PRODUCT_ISSUE.bp * 10000 ,'FM9999999999999990.90') || ' BP' else to_char(FIN_PRODUCT_ISSUE.REFER_YIELD * 100 ,'FM9999999999999990.9000') || ' %' END WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F17' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS IN ('02','03') THEN TO_CHAR(BIDT.BID_PRICE) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F05', 'F04', 'F03', 'F09', 'F06', 'F02') THEN TO_CHAR(round( 0, 4 )) WHEN ETR_ENTRUST.PS IN ('T68', 'T69') THEN TO_CHAR(ETR_ENTRUST.PRICE * 100) WHEN ETR_ENTRUST.PS IN ('T56', 'T93', 'T94', 'T95', 'T96') THEN TO_CHAR(ETR_ENTRUST.PRICE * 100) ELSE TO_CHAR(nvl(round(decode(btm.busi_type, '02', decode(ETR_ENTRUST_ADD.CALCULATE_FIELD, 'price', ETR_ENTRUST.PRICE, 'exerYield', ETR_ENTRUST_ADD.EXER_YIELD * 100, 'matureYield', ETR_ENTRUST_ADD.MATURE_YIELD * 100), '03', ETR_ENTRUST.PRICE, '05', ETR_ENTRUST.PRICE * 100, nvl(ETR_ENTRUST.PRICE , 0)), 4), round(nvl(ETR_ENTRUST.PRICE , 0), 4))) END AS etrPrice, CASE WHEN ETR_ENTRUST.TRADE_MARKET = '03' OR ETR_ENTRUST.TRADE_MARKET = '04' THEN ( CASE
WHEN ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T9.ORDER_FINISH_AMT, 0 ), 0, 0,nvl( T9.ORDER_FINISH_AMT, 0 )/ nvl( ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( decode(nvl( T9.ORDER_FINISH_AMT, 0 ) ,0,0,nvl( T9.ORDER_FINISH_AMT, 0 )/ nvl( etr_entrust.ENTRUST_AMT, 1 )), 4 ) * 100 END ) ELSE ( CASE
WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM != 0 THEN trunc( nvl( NVL( T7.FINISH_AMT, 0 ) + NVL( T5.ENT_FINISH_AMT * 100, 0 ), 0 ) / ( ETR_ENTRUST.ENTRUST_NUM * 100 ), 4 ) * 100 WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM = 0 THEN 0 WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F17' THEN trunc( nvl( NVL( T7.FINISH_AMT, 0 ) + NVL( T5.ENT_FINISH_AMT * 100, 0 ), 0 ) / ( ETR_ENTRUST.ENTRUST_NUM * 100 ), 4 ) * 100 WHEN ETR_ENTRUST.ENTRUST_AMT = 0 THEN 0 ELSE trunc( nvl( nvl( T7.FINISH_AMT, 0 ) + nvl( T5.ENT_FINISH_AMT, 0 ), 0 ) / ETR_ENTRUST.ENTRUST_AMT, 4 ) * 100 END ) END AS exeProgress, CASE
WHEN ETR_ENTRUST.TRADE_MARKET = '03' OR ETR_ENTRUST.TRADE_MARKET = '04' THEN ( CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T9.ENT_FINISH_AMT, 0 ),0,0, nvl( T9.ENT_FINISH_AMT, 0 )/ nvl( etr_entrust.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( decode(nvl( T9.ENT_FINISH_AMT, 0 ),0,0,nvl( T9.ENT_FINISH_AMT, 0 )/ nvl( etr_entrust.ENTRUST_AMT, 1 )), 4 ) * 100 END ) ELSE ( CASE
WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM != 0 THEN ( CASE
WHEN ETR_ENTRUST.ENTRUST_NUM != '0' THEN trunc( ( NVL( CB.totalShareAmt, nvl( C2B.totalShareAmt, 0 ) ) + NVL( T6.FINISH_AMT * 100, 0 ) + NVL( T5.FINISH_AMT * 100, 0 ) ) / ( ETR_ENTRUST.ENTRUST_NUM * 100 ), 4 ) * 100 ELSE 0 END ) WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM = 0 THEN 0 WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ( 'F02', 'F05' ) THEN round( nvl( ETR_FINISH_STATUS_A.FINISH_AMT, 0 ) / NVL( ETR_ENTRUST.ENTRUST_AMT, ETR_ENTRUST.ENTRUST_NUM ), 4 ) * 100 WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ( 'F10', 'F08', 'F10', 'F04', 'F03', 'F09', 'F06' ) THEN round( NVL( T10.FINISH_AMT, 0 ) / NVL( ETR_ENTRUST.ENTRUST_NUM, ETR_ENTRUST.ENTRUST_AMT ), 4 ) * 100 WHEN ( ETR_ENTRUST.ENTRUST_AMT = 0 OR ETR_ENTRUST.ENTRUST_AMT IS NULL ) THEN 0 ELSE trunc( ( nvl( C.totalShareAmt, nvl( C2.FPRICE_AMT, 0 ) ) + nvl( T6.FINISH_AMT, 0 ) + NVL( T5.FINISH_AMT, 0 ) ) / ETR_ENTRUST.ENTRUST_AMT, 4 ) * 100 END ) END AS dealProgress, CASE
WHEN ETR_ENTRUST.TRADE_MARKET = '03' OR ETR_ENTRUST.TRADE_MARKET = '04' THEN ( CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( T9.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T9.ORDER_FINISH_AMT, 0 ), 4 ) END ) ELSE ( CASE
WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' THEN ( NVL( T7.FINISH_AMT, 0 ) + NVL( T5.ENT_FINISH_AMT * 100, 0 ) ) / 10000 ELSE round( ( NVL( T7.FINISH_AMT, 0 ) + NVL( T5.ENT_FINISH_AMT, 0 ) ) / 10000, 2 ) END ) END AS execFinishAmt, CASE
WHEN ETR_ENTRUST.TRADE_MARKET = '03' OR ETR_ENTRUST.TRADE_MARKET = '04' THEN ( CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T9.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_entrust.ENTRUST_AMT, 0 ) - nvl( T9.ORDER_FINISH_AMT, 0 ), 4 ) END ) ELSE ( CASE
WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' THEN NVL( ETR_ENTRUST.ENTRUST_NUM, 0 ) / 100 - NVL( T7.FINISH_AMT, 0 ) / 10000 - NVL( T5.ENT_FINISH_AMT, 0 ) / 100 ELSE round( ( NVL( ETR_ENTRUST.ENTRUST_AMT, 0 ) - NVL( T7.FINISH_AMT, 0 ) - NVL( T5.ENT_FINISH_AMT, 0 ) ) / 10000, 2 ) END ) END AS execRemainderAmt, CASE
WHEN ETR_ENTRUST.TRADE_MARKET = '03' OR ETR_ENTRUST.TRADE_MARKET = '04' THEN ( CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( T9.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T9.ENT_FINISH_AMT, 0 ), 4 ) END ) ELSE ( CASE
WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' THEN ROUND( NVL( CB.totalShareAmt, nvl( C2B.totalShareAmt, 0 ) ) + NVL( T6.FINISH_AMT * 100, 0 ) ) / 10000 ELSE ROUND( ( NVL( C.totalShareAmt, nvl( C2.FPRICE_AMT, 0 ) ) + NVL( T6.FINISH_AMT, 0 ) ) / 10000, 2 ) END ) END AS transFinishAmt, CASE
WHEN ETR_ENTRUST.TRADE_MARKET = '03' OR ETR_ENTRUST.TRADE_MARKET = '04' THEN ( CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T9.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_entrust.ENTRUST_AMT, 0 ) - nvl( T9.ENT_FINISH_AMT, 0 ), 4 ) END ) ELSE ( CASE
WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' THEN NVL( ETR_ENTRUST.ENTRUST_NUM, 0 ) / 100 - ROUND( NVL( CB.totalShareAmt, nvl( C2B.totalShareAmt, 0 ) ) + NVL( T6.FINISH_AMT * 100, 0 ) ) / 10000 ELSE ROUND( ( NVL( ETR_ENTRUST.ENTRUST_AMT, 0 ) - NVL( C.totalShareAmt, nvl( C2.FPRICE_AMT, 0 ) ) + NVL( T6.FINISH_AMT, 0 ) ) / 10000, 2 ) END ) END AS transRemainderAmt, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi') transmitTimeSer, ETR_ENTRUST_ADD.CALCULATE_FIELD FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID LEFT JOIN (select ENTRUST_ID ,PORTFOLIO_ID from(select ol.ENTRUST_ID,ol.PORTFOLIO_ID, row_number() OVER(PARTITION BY ol.ENTRUST_ID ORDER BY ol.ENTRUST_ID) ds from ETR_ENTRUST_DETAIL ol where ol.ENTRUST_ID is not null) where ds = 1 ) det2 ON det2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON (PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID OR PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = det2.PORTFOLIO_ID) LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT,SUM(Ent_Finish_Amt) as Ent_Finish_Amt FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN(SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, SUM(nvl(iqer.FPRICE_AMT, 0)) totalShareAmt FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07') GROUP BY iqer.ENTRUST_ID) C /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, iqer.FPRICE_AMT FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07')) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) CB ON CB.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2B ON C2B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN SYS_USER su1 ON ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME LEFT JOIN FIN_PRODUCT_ISSUE ON FIN_PRODUCT_ISSUE.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps, INPUT_VALUE_3 AS issueClass, OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON ETR_ENTRUST_ADD.ASSET_TYPE = btm.Finprod_Type_Tg AND ETR_ENTRUST.Ps = btm.ps AND (btm.issueClass = FIN_PRODUCT_ISSUE.ISSUE_CLASS OR btm.issueClass IS NULL ) LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm1 ON ( ETR_ENTRUST.FINPROD_TYPE2 = btm1.INPUT_VALUE_2 OR btm1.INPUT_VALUE_2 IS NULL) AND ( ETR_ENTRUST.Ps = btm1.INPUT_VALUE_3 OR btm1.INPUT_VALUE_3 IS NULL) AND ( ETR_ENTRUST.TRADE_PLAT = btm1.INPUT_VALUE_1 OR btm1.INPUT_VALUE_1 IS NULL) LEFT JOIN (SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T10 ON ETR_ENTRUST.ENTRUST_ID = T10.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, wm_concat ( ETR_ENTRUST_DETAIL.PORTFOLIO_ID ) PORTFOLIO_ID, wm_concat ( PORTFOLIO_NAME ) PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL LEFT JOIN (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) PTL_PORTFOLIO ON ETR_ENTRUST_DETAIL.portfolio_id = PTL_PORTFOLIO.portfolio_id GROUP BY ENTRUST_ID ) det on det.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT LISTAGG(TO_CHAR(BID_PRICE,'FM9999999999999990.9000') , ',') WITHIN GROUP (ORDER BY (BID_PRICE)) BID_PRICE, ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID ) BIDT ON BIDT.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on FIN_PRODUCT_ISSUE.INT_RATE_ID = SDLDATA.ITEM_CODE LEFT JOIN ( SELECT LISTAGG(eed.SEC_ACCT_ID, ',') WITHIN GROUP (ORDER BY (eed.SEC_ACCT_ID)) SEC_ACCT_ID, LISTAGG(ssai.SEC_ACCT_NAME, ',') WITHIN GROUP (ORDER BY (ssai.SEC_ACCT_NAME)) SEC_ACCT_NAME, eed.ENTRUST_ID ENTRUST_ID FROM ETR_ENTRUST_DETAIL eed LEFT JOIN STL_SEC_ACCT_INFO ssai ON eed.SEC_ACCT_ID = ssai.SEC_ACCT_ID GROUP BY ENTRUST_ID ) SECT ON SECT.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
LEFT JOIN ETR_FINISH_STATUS T9 ON T9.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID AND ETR_ENTRUST.ENTRUST_ID = T9.TRADE_ID
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND (ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
) OR ETR_ENTRUST.PORTFOLIO_ID IS NULL)
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND fpt.TYPE_9 = #{TYPE_9}
AND (btm.busi_type = #{busiTypePosition} OR btm1.OUTPUT_VALUE_1 = #{busiTypePosition})
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
) t left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='STATUS_VALID' and t.effectFlag=sdl.ITEM_CODE left join SYS_DATADICT_LIST sdl1 on sdl1.DICT_CODE='ENTRUST_STATUS' and t.entrustStatus=sdl1.ITEM_CODE left join SYS_DATADICT_LIST sdl2 on sdl2.DICT_CODE='PINAN_ASSET_TYPE' and t.finprodType2=sdl2.ITEM_CODE left join SYS_DATADICT_LIST sdl3 on sdl3.DICT_CODE='BUSI_TYPE_POSITION' and t.busiTypePosition=sdl3.ITEM_CODE left join SYS_DATADICT_LIST sdl4 on sdl4.DICT_CODE='PS' and t.PS=sdl4.ITEM_CODE left join SYS_DATADICT_LIST sdl5 on sdl5.DICT_CODE='TRADE_PLACE' and t.tradeMarket=sdl5.ITEM_CODE left join SYS_DATADICT_LIST sdl6 on sdl6.DICT_CODE='ACCOUNT_SPEED' and t.settleSpeed=sdl6.ITEM_CODE left join SYS_DATADICT_LIST sdl7 on sdl7.DICT_CODE='CCY' and t.ccy=sdl7.ITEM_CODE left join SYS_DATADICT_LIST sdl8 on sdl8.DICT_CODE='FIRST_BID_STATUS' and t.firstBidStatus=sdl8.ITEM_CODE
AND t.firstBidStatus = #{firstBidStatus}
AND
(INSTR(t.portfolioId,concat(#{item},','))>0 OR INSTR(t.portfolioId,concat(#{item},','))>0 OR t.portfolioId = #{item} )
order by t.entrustStatusOrder,t.transmitTime,t.finprodType2,t.finprodMarketId,t.ps)
order by ${sort} ${direction}

