SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, mci2.CALENDAR_NAME calendarName, eted.ASSET_TYPE1 assetType1, eted.ASSET_TYPE_10 assetType10, eted.ASSET_TYPE_11 assetType11, ete.PRICE price, ssai.sec_acct_name secAcctId, fpa.TRM_FUND_TYPE trmFundType, fpa.TRM_FUND_ABBR trmFundAbbr, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, CASE WHEN det.PORTFOLIO_ID IS NULL THEN ete.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, pp.portfolio_name portfolioName, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, ete.ccy ccy, ete.remark remark, ete.ENTRUST_NUM shareNum, ete.entrust_amt shareAmt, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, ete.PRICE * 100 rate FROM ETR_ENTRUST ete INNER JOIN ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON ete.finprod_id = fpa.finprod_id LEFT JOIN (SELECT ENTRUST_ID, wm_concat(PORTFOLIO_ID) PORTFOLIO_ID from ETR_ENTRUST_DETAIL GROUP BY ENTRUST_ID) det on det.ENTRUST_ID = ete.ENTRUST_ID WHERE ete.entrust_id = #{entrustId}
union
SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, mci2.CALENDAR_NAME calendarName, eted.ASSET_TYPE1 assetType1, eted.ASSET_TYPE_10 assetType10, eted.ASSET_TYPE_11 assetType11, ete.PRICE price, ssai.sec_acct_name secAcctId, fpa.TRM_FUND_TYPE trmFundType, fpa.TRM_FUND_ABBR trmFundAbbr, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, CASE WHEN det.PORTFOLIO_ID IS NULL THEN ete.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, pp.portfolio_name portfolioName, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, ete.ccy ccy, ete.remark remark, ete.ENTRUST_NUM shareNum, ete.entrust_amt shareAmt, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, ete.PRICE * 100 rate FROM WFL_ETR_ENTRUST ete INNER JOIN WFL_ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON ete.finprod_id = fpa.finprod_id LEFT JOIN (SELECT ENTRUST_ID, wm_concat(PORTFOLIO_ID) PORTFOLIO_ID from WFL_ETR_ENTRUST_DETAIL GROUP BY ENTRUST_ID) det on det.ENTRUST_ID = ete.ENTRUST_ID WHERE ete.entrust_id = #{entrustId}

select T.* from( SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, T4.TARGET_FINPROD_ID targetFinprodId, NVL ( T5.FINPROD_ABBR, T5.FINPROD_NAME ) targetFinprodName, mci2.CALENDAR_NAME calendarName, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, eted.MIN_AMT minAmt, eted.ASSET_TYPE1 paBussType, CASE WHEN det.PORTFOLIO_ID IS NULL THEN ete.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, pp.portfolio_name portfolioName, ete.BUSINESS_MODEL busiModel, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, DECODE(eted.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, ete.price_model priceModel, ssai.sec_acct_name secAcctId, ete.ccy ccy, decode( eted.ASSET_TYPE, 'F01', NVL( ete.ENTRUST_NUM / 100, 0 ), 'F10', NVL( ete.ENTRUST_NUM * 100, 0 ), NVL( ete.ENTRUST_AMT, ete.ENTRUST_NUM )) shareNum, eted.our_ent_num/100 entrustOwnNum, eted.lendin_ent_num integrateSecAmount, ete.price unitPrice, eted.full_price allPrice, eted.mature_yield*100 matureYield, eted.exer_yield*100 exerYield, eted.full_price*ete.entrust_num fpriceAmt, ete.remark remark, mci.CUSTOMER_NAME mainConsignee, to_char(eted.payment_date,'yyyy-MM-dd') paymentDate, to_char(eted.listing_date,'yyyy-MM-dd') listingDate, ete.entrust_num entrustNum, ete.entrust_amt entrustAmt, eted.deal_mode dealMode, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, to_char(eted.MDATE,'yyyy-MM-dd') || ' - ' || to_char(eted.MDATE2,'yyyy-MM-dd') as dueDate, eted.TERM_DAYS repoTerm, eted.FIRST_UNIT_CPRICE || ' - ' || eted.FIRST_UNIT_CPRICE2 firstprice, pss.pledge_stock_name pledgeStockName, fp.Is_Right isRight, ete.PRICE * 100 rate FROM ETR_ENTRUST ete INNER JOIN ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = eted.main_consignee AND mci.IS_SALER = #{YESORNO_YES, jdbcType = VARCHAR} LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN ETR_TARGET T4 ON ete.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID LEFT JOIN ( SELECT ENTRUST_ID, wm_concat ( PORTFOLIO_ID ) PORTFOLIO_ID FROM ETR_ENTRUST_DETAIL GROUP BY ENTRUST_ID ) det ON det.ENTRUST_ID = ete.ENTRUST_ID WHERE ete.entrust_id = #{entrustId}
union
SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, T4.TARGET_FINPROD_ID targetFinprodId, NVL ( T5.FINPROD_ABBR, T5.FINPROD_NAME ) targetFinprodName, mci2.CALENDAR_NAME calendarName, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, eted.MIN_AMT minAmt, eted.ASSET_TYPE1 paBussType, CASE WHEN det.PORTFOLIO_ID IS NULL THEN ete.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, pp.portfolio_name portfolioName, ete.BUSINESS_MODEL busiModel, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, DECODE(eted.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, ete.price_model priceModel, ssai.sec_acct_name secAcctId, ete.ccy ccy, decode( eted.ASSET_TYPE, 'F01', NVL( ete.ENTRUST_NUM * 100, 0 ), 'F10', NVL( ete.ENTRUST_NUM * 100, 0 ), NVL( ete.ENTRUST_AMT, ete.ENTRUST_NUM )) shareNum, eted.our_ent_num/100 entrustOwnNum, eted.lendin_ent_num integrateSecAmount, ete.price unitPrice, eted.full_price allPrice, eted.mature_yield*100 matureYield, eted.exer_yield*100 exerYield, eted.full_price*ete.entrust_num fpriceAmt, ete.remark remark, mci.CUSTOMER_NAME mainConsignee, to_char(eted.payment_date,'yyyy-MM-dd') paymentDate, to_char(eted.listing_date,'yyyy-MM-dd') listingDate, ete.entrust_num entrustNum, ete.entrust_amt entrustAmt, eted.deal_mode dealMode, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, to_char(eted.MDATE,'yyyy-MM-dd') || ' - ' || to_char(eted.MDATE2,'yyyy-MM-dd') as dueDate, eted.TERM_DAYS repoTerm, eted.FIRST_UNIT_CPRICE || ' - ' || eted.FIRST_UNIT_CPRICE2 firstprice, pss.pledge_stock_name pledgeStockName, fp.Is_Right isRight, ete.PRICE * 100 rate FROM WFL_ETR_ENTRUST ete INNER JOIN WFL_ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = eted.main_consignee AND mci.IS_SALER = #{YESORNO_YES, jdbcType = VARCHAR} LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN ETR_TARGET T4 ON ete.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID LEFT JOIN ( SELECT ENTRUST_ID, wm_concat ( PORTFOLIO_ID ) PORTFOLIO_ID FROM WFL_ETR_ENTRUST_DETAIL GROUP BY ENTRUST_ID ) det ON det.ENTRUST_ID = ete.ENTRUST_ID WHERE ete.entrust_id = #{entrustId}) T where rownum <=1

