FROM T_TRADE a left join T_INSTRUCTION b on a.INSTRUCTION_ID =b.ENTRUST_ID where a.INSTRUCTION_ID = #{instructionId,jdbcType=VARCHAR} UNION ALL select
FROM T_TRADEHISTORY a left join T_INSTRUCTION b on a.INSTRUCTION_ID =b.ENTRUST_ID where a.INSTRUCTION_ID = #{instructionId,jdbcType=VARCHAR}
